  4	public final class RadixSort {
  5	    private static final int RADIX = 10;
  6	
  7	    private RadixSort() {
  8	    }
  9	
 10	    public static void sort(int[] values) {
 11	        sortValidated(requireSupportedValues(values));
 12	    }
 13	
 14	    public static int[] sortedCopy(int[] values) {
 15	        int[] copy = copyOfSupportedValues(values);
 16	        sortValidated(copy);
 17	        return copy;
 18	    }
 19	
 20	    private static void sortValidated(int[] values) {
 21	        if (values.length < 2) {
 22	            return;
 23	        }
 24	
 25	        SortWorkspace workspace = new SortWorkspace(values);
 26	        int maxValue = findMax(values);
 27	
 28	        for (long exponent = 1; maxValue / exponent > 0; exponent *= RADIX) {
 29	            countingSortByDigit(
 30	                workspace.source(),
 31	                workspace.target(),
 32	                workspace.counts(),
 33	                exponent
 34	            );
 35	            workspace.swapBuffers();
 36	        }
 37	
 38	        workspace.copyResultBackIfNeeded();
 39	    }
 40	
 41	    private static int[] requireSupportedValues(int[] values) {
 42	        Objects.requireNonNull(values, "values");
 43	
 44	        for (int value : values) {
 45	            if (value < 0) {
 46	                throw new IllegalArgumentException(
 47	                    "Radix sort only supports non-negative integers."
 48	                );
 49	            }
 50	        }
 51	
 52	        return values;
 53	    }
 54	
 55	    private static int[] copyOfSupportedValues(int[] values) {
 56	        int[] validatedValues = requireSupportedValues(values);
 57	        return Arrays.copyOf(validatedValues, validatedValues.length);
 58	    }
 59	
 60	    private static int findMax(int[] values) {
 61	        int maxValue = values[0];
 62	        for (int index = 1; index < values.length; index++) {
 63	            if (values[index] > maxValue) {
 64	                maxValue = values[index];
 65	            }
 66	        }
 67	        return maxValue;
 68	    }
 69	
 70	    private static void countingSortByDigit(
 71	        int[] source,
 72	        int[] target,
 73	        int[] counts,
 74	        long exponent
 75	    ) {
 76	        Arrays.fill(counts, 0);
 77	
 78	        for (int value : source) {
 79	            counts[digitAt(value, exponent)]++;
 80	        }
 81	
 82	        for (int digit = 1; digit < RADIX; digit++) {
 83	            counts[digit] += counts[digit - 1];
 84	        }
 85	
 86	        for (int index = source.length - 1; index >= 0; index--) {
 87	            int value = source[index];
 88	            int digit = digitAt(value, exponent);
 89	            target[--counts[digit]] = value;
 90	        }
 91	    }
 92	
 93	    private static int digitAt(int value, long exponent) {
 94	        return (int) ((value / exponent) % RADIX);
 95	    }
 96	
 97	    private static final class SortWorkspace {
 98	        private final int[] originalValues;
 99	        private final int[] buffer;
100	        private final int[] counts = new int[RADIX];
101	        private int[] source;
102	        private int[] target;
103	
104	        private SortWorkspace(int[] values) {
105	            this.originalValues = values;
106	            this.buffer = new int[values.length];
107	            this.source = values;
108	            this.target = buffer;
109	        }
110	
111	        private int[] source() {
112	            return source;
113	        }
114	
115	        private int[] target() {
116	            return target;
117	        }
118	
119	        private int[] counts() {
120	            return counts;
121	        }
122	
123	        private void swapBuffers() {
124	            int[] previousSource = source;
125	            source = target;
126	            target = previousSource;
127	        }
128	
129	        private void copyResultBackIfNeeded() {
130	            if (source != originalValues) {
131	                System.arraycopy(source, 0, originalValues, 0, originalValues.length);
132	            }
133	        }
134	    }
135	}

